versions.variantCss:
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] {
  background: var(--wemd-bg-soft);
  border-radius: var(--wemd-border-radius);
  padding: 24px 28px;
  margin: 16px 0;
  border-left: 4px solid var(--wemd-primary);
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-quote {
  color: var(--wemd-text-strong);
  font-size: 16px;
  font-style: italic;
  line-height: 1.75;
  margin: 0 0 16px 0;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-source {
  display: flex;
  align-items: center;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  margin-right: 12px;
  overflow: hidden;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-avatar img {
  width: 100%;
  height: 100%;
  display: block;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-person {
  flex: 1;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-person-meta {
  display: flex;
  align-items: center;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-name {
  color: var(--wemd-text-strong);
  font-size: 14px;
  font-weight: 700;
  margin-right: 8px;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-title {
  color: var(--wemd-text-soft);
  font-size: 12px;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-company {
  color: var(--wemd-primary);
  font-size: 12px;
  font-weight: 500;
  margin-top: 2px;
}
.wemd-testimonial-card[data-variant="bytedance-testimonial-quote"] .wemd-tc-company-logo {
  width: 24px;
  height: 24px;
  margin-left: 8px;
}
